CREATE TABLE `bank_accounts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `uid` varchar(64) NOT NULL,
  `is_qris` tinyint(4) NOT NULL DEFAULT 0,
  `bank_name` varchar(100) DEFAULT NULL,
  `account_number` varchar(50) DEFAULT NULL,
  `account_holder` varchar(100) DEFAULT NULL,
  `qris_url` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `qris_slot` tinyint(4) GENERATED ALWAYS AS (case when `is_qris` = 1 then 1 else NULL end) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bank_accounts_owner_bank_number` (`uid`,`bank_name`,`account_number`),
  UNIQUE KEY `uq_bank_accounts_owner_qris` (`uid`,`qris_slot`),
  CONSTRAINT `fk_bank_accounts_user` FOREIGN KEY (`uid`) REFERENCES `users` (`uid`) ON DELETE CASCADE,
  CONSTRAINT `ck_bank_accounts_type` CHECK (`is_qris` = 0 and `bank_name` is not null and `account_number` is not null and `account_holder` is not null and `qris_url` is null or `is_qris` = 1 and `bank_name` is null and `account_number` is null and `account_holder` is null and `qris_url` is not null and `qris_url` <> '')
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
